def transform(grid):
    out = [row[:] for row in grid]
    bg = 0
    for r, row in enumerate(grid):
        nz = [i for i, v in enumerate(row) if v != bg]
        if not nz: continue
        # For a horizontal stripe/object row, recolor trailing background after its final mark.
        last = nz[-1]
        if last < len(row)-1 and r >= 14 and r <= 17:
            for c in range(last+1, len(row)):
                out[r][c] = 1
    return out
